pub fn adaptive_sort<T: Ord>(a: &mut [T]) {
    let n = a.len();
    if n <= 20 { ins(a); return; }
    q(a, 0, n - 1);
}

fn ins<T: Ord>(a: &mut [T]) {
    for i in 1..a.len() {
        let mut j = i;
        while j > 0 && a[j - 1] > a[j] { a.swap(j, j - 1); j -= 1; }
    }
}

fn q<T: Ord>(a: &mut [T], lo: usize, hi: usize) {
    if hi - lo < 20 { ins(&mut a[lo..=hi]); return; }
    let mid = lo + (hi - lo) / 2;
    if a[lo] > a[mid] { a.swap(lo, mid); }
    if a[lo] > a[hi] { a.swap(lo, hi); }
    if a[mid] > a[hi] { a.swap(mid, hi); }
    a.swap(mid, hi - 1);
    let mut i = lo + 1;
    let mut j = hi - 2;
    loop {
        while a[i] < a[hi - 1] { i += 1; }
        while a[j] > a[hi - 1] { j -= 1; }
        if i >= j { break; }
        a.swap(i, j);
        i += 1; j -= 1;
    }
    a.swap(i, hi - 1);
    if i > lo + 1 { q(a, lo, i - 1); }
    if i + 1 < hi { q(a, i + 1, hi); }
}
